// Splits a bill (in agorot, a whole number) between people by weights.
// Uses exact BigInt arithmetic on the decimal form of each weight, so floating
// point error (e.g. weights 0.1 and 0.2) cannot affect the result.
function toScaled(weights) {
  const parsed = weights.map((w) => {
    const m = /^(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/.exec(String(Number(w)));
    if (!m) throw new Error("bad weights");
    const frac = m[2] || "";
    return { digits: BigInt(m[1] + frac), exp: (m[3] ? Number(m[3]) : 0) - frac.length };
  });
  const minExp = Math.min(...parsed.map((p) => p.exp));
  return parsed.map((p) => p.digits * 10n ** BigInt(p.exp - minExp));
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => !(w > 0))) throw new Error("bad weights");
  if (weights.some((w) => !Number.isFinite(Number(w)))) throw new Error("bad weights");
  const scaled = toScaled(weights);
  const sum = scaled.reduce((a, b) => a + b, 0n);
  const T = BigInt(total);
  const shares = [];
  const rems = [];
  let given = 0n;
  for (const w of scaled) {
    const num = T * w;
    const q = num / sum;
    shares.push(q);
    rems.push(num % sum);
    given += q;
  }
  const leftover = Number(T - given);
  const order = weights
    .map((_, i) => i)
    .sort((a, b) => (rems[a] === rems[b] ? a - b : rems[a] > rems[b] ? -1 : 1));
  for (let k = 0; k < leftover; k++) shares[order[k]] += 1n;
  return shares.map(Number);
}
module.exports = { splitBill };
