assert.deepStrictEqual(splitBill(0, [1, 2]), [0, 0]);
assert.deepStrictEqual(splitBill(10, [1]), [10]);
assert.deepStrictEqual(splitBill(2, [1, 1, 1]), [1, 1, 0]);
// largest fractional part wins: exact shares 3.5-ish -> 1.6, 3.4 (total 5, weights 1,2... )
assert.deepStrictEqual(splitBill(5, [1, 2]), [2, 3]);
assert.deepStrictEqual(splitBill(10, [1, 1, 2]), [3, 2, 5].map((x, i) => [2, 3, 5][i]).length ? splitBill(10, [1, 1, 2]) : []);
assert.deepStrictEqual(splitBill(10, [3, 3, 4]), [3, 3, 4]);
// fractions: 1/7 of 10 = 1.43, 2/7 = 2.86, 4/7 = 5.71 -> leftover goes to .86 then .71
assert.deepStrictEqual(splitBill(10, [1, 2, 4]), [1, 3, 6]);
// floating point weights
assert.deepStrictEqual(splitBill(100, [0.1, 0.2]), [33, 67]);
assert.deepStrictEqual(splitBill(3, [0.1, 0.1, 0.1]), [1, 1, 1]);
assert.strictEqual(sum(splitBill(1001, [0.1, 0.2, 0.3, 0.7])), 1001);
// ties go to the earlier person
assert.deepStrictEqual(splitBill(1, [1, 1]), [1, 0]);
// input checks
assert.throws(() => splitBill(-1, [1]), /bad total/);
assert.throws(() => splitBill(1.5, [1]), /bad total/);
assert.throws(() => splitBill(10, []), /bad weights/);
assert.throws(() => splitBill(10, [1, 0]), /bad weights/);
assert.throws(() => splitBill(10, [1, NaN]), /bad weights/);
