// "HH:MM" <-> minutes since midnight, and "HH:MM-HH:MM" ranges.
function parseTime(s) {
  const m = /^(\d{2}):(\d{2})$/.exec(String(s).trim());
  if (!m || Number(m[1]) > 23 || Number(m[2]) > 59) throw new Error("bad time: " + s);
  return Number(m[1]) * 60 + Number(m[2]);
}
function parseRange(s) {
  const parts = String(s).split("-");
  if (parts.length !== 2) throw new Error("bad range: " + s);
  const start = parseTime(parts[0]), end = parseTime(parts[1]);
  if (end <= start) throw new Error("range ends before it starts: " + s);
  return { start, end };
}
function formatMinutes(m) {
  const h = Math.floor(m / 60), min = m % 60;
  return String(h).padStart(2, "0") + ":" + String(min).padStart(2, "0");
}
module.exports = { parseTime, parseRange, formatMinutes };
