const { parseTime, parseRange, formatMinutes } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen) {
  const ds = parseTime(dayStart), de = parseTime(dayEnd);
  if (de <= ds) throw new Error("day ends before it starts");
  const ranges = busy.map(parseRange).sort((a, b) => a.start - b.start || a.end - b.end);
  const out = [];
  let cursor = ds;
  for (const r of ranges) {
    if (r.end <= cursor) continue;
    if (r.start >= de) break;
    if (r.start > cursor && r.start - cursor >= minLen) {
      out.push(formatMinutes(cursor) + "-" + formatMinutes(r.start));
    }
    cursor = Math.max(cursor, r.end);
  }
  if (de > cursor && de - cursor >= minLen) {
    out.push(formatMinutes(cursor) + "-" + formatMinutes(de));
  }
  return out;
}

module.exports = { freeSlots };
